/* Ocean Blue Theme — Professional, trustworthy */
:root {
    --theme-primary: #0ea5e9;
    --theme-primary-dark: #0284c7;
    --theme-primary-light: #e0f2fe;
    --theme-accent: #0369a1;
    --theme-bg: #ffffff;
    --theme-bg-alt: #f8fafc;
    --theme-text: #0f172a;
    --theme-text-secondary: #475569;
    --theme-text-muted: #94a3b8;
    --theme-border: #e2e8f0;
    --theme-shadow: rgba(14, 165, 233, 0.1);
    /* 图表/多色标签辅助色（chart-blue 用靛蓝区别于主题的海洋蓝，避免撞色） */
    --theme-chart-blue: #6366f1;
    --theme-chart-green: #16a34a;
    --theme-chart-purple: #7c3aed;
    --theme-chart-yellow: #d97706;
}

body {
    background: var(--theme-bg);
    color: var(--theme-text);
}

.proposal-header {
    background: linear-gradient(135deg, var(--theme-primary) 0%, var(--theme-primary-dark) 100%);
    color: white;
}

.proposal-section-title {
    color: var(--theme-primary-dark);
    border-bottom: 2px solid var(--theme-primary-light);
}

.proposal-highlight {
    background: var(--theme-primary-light);
    border-left: 4px solid var(--theme-primary);
}

.proposal-cta {
    background: var(--theme-primary);
    color: white;
}

.proposal-cta:hover {
    background: var(--theme-primary-dark);
}

.proposal-price {
    color: var(--theme-primary-dark);
}

.proposal-table th {
    background: var(--theme-primary-light);
    color: var(--theme-primary-dark);
}

.proposal-card {
    border: 1px solid var(--theme-border);
    box-shadow: 0 4px 6px var(--theme-shadow);
}

.proposal-card:hover {
    border-color: var(--theme-primary);
}

.proposal-footer {
    background: var(--theme-bg-alt);
    border-top: 1px solid var(--theme-border);
}

